const KNOWN_LONG_OPTIONS = new Set(Object.keys(CLI_OPTIONS));

// Short-option long-names that parseArgs resolves a `-x` to (e.g. -h -> "help").
const KNOWN_SHORT_OPTIONS = new Set(
  Object.entries(CLI_OPTIONS)
    .filter(([, spec]) => spec.short !== undefined)
    .map(([name]) => name),
);

export function parseCli(argv: string[]): { values: CliValues; positionals: string[] } {
  // parseArgs runs with strict:false so we can emit friendly CliUsageErrors for
  // bundled-short flags, bare string flags, and removed options. The cost is
  // that parseArgs would otherwise silently ignore unknown options, which is
  // dangerous for removed safety flags like the old --read-only: a user who
  // believes they enabled read-only would have write tools left exposed. We
  // guard against that below using the token stream, which is the authority on
  // what is an option vs a positional — including correctly treating tokens
  // after the "--" terminator as positionals.
  const parsed = parseArgs({
    args: argv,
    options: CLI_OPTIONS,
    allowPositionals: true,
    strict: false,
    tokens: true,
  });
  const { values: raw, positionals, tokens } = parsed;

  // Count short-option occurrences per source argv index so we can detect
  // bundles like `-xy` (two tokens, same index) and repeats like `-hh`.
  const shortOptionCountByIndex = new Map<number, number>();
  for (const token of tokens) {
    if (token.kind === "option" && token.rawName.startsWith("-") && !token.rawName.startsWith("--")) {
      shortOptionCountByIndex.set(token.index, (shortOptionCountByIndex.get(token.index) ?? 0) + 1);
    }
  }

  for (const token of tokens) {
    if (token.kind !== "option") continue;
    if (token.rawName.startsWith("--")) {
      // Long option (e.g. --market, --read-only). Reject if not defined.
      // Echo the original argv token (e.g. --bogus=1) rather than the
      // normalized token.name so the message matches what the user typed.
      if (!KNOWN_LONG_OPTIONS.has(token.name)) {
        throw new CliUsageError(`unknown option: '${argv[token.index]}'`);
      }
    } else {
      // Short option (e.g. -h). Reject bundles/repeats (more than one short
      // option from a single argv token, e.g. -xy or -hh) and undefined shorts.
      if ((shortOptionCountByIndex.get(token.index) ?? 0) > 1 || !KNOWN_SHORT_OPTIONS.has(token.name)) {
        throw new CliUsageError(`unknown option: '${argv[token.index]}'`);
      }
    }
  }

  // Guard: string-type options must not receive a bare flag (--count without a value
  // causes parseArgs to produce `true` instead of a string).
  for (const [key, spec] of Object.entries(CLI_OPTIONS)) {
    if (spec.type === "string" && raw[key] === true) {
      throw new CliUsageError(`option '--${key}' requires a value`);
    }
  }

  // Map kebab-case to camelCase
  const values: CliValues = {
    profile: raw.profile as string | undefined,
    json: raw.json as boolean | undefined,
    help: raw.help as boolean | undefined,
    version: raw.version as boolean | undefined,
    verbose: raw.verbose as boolean | undefined,
    client: raw.client as string | undefined,
    modules: raw.modules as string | undefined,
    unit: raw.unit as string | undefined,
    count: raw.count as string | undefined,
    to: raw.to as string | undefined,
    isDetails: raw["is-details"] as boolean | undefined,
    market: raw.market as string | undefined,
    clientOrderId: raw["client-order-id"] as string | undefined,
    side: raw.side as string | undefined,
    // Canonical: --order-type. Deprecated alias: --ord-type. Prefer canonical.
    ordType:
      (raw["order-type"] as string | undefined) ??
      (raw["ord-type"] as string | undefined),
    ordTypeFromDeprecatedAlias:
      (raw["order-type"] as string | undefined) === undefined &&
      (raw["ord-type"] as string | undefined) !== undefined,
    ordTypeConflict:
      (raw["order-type"] as string | undefined) !== undefined &&
      (raw["ord-type"] as string | undefined) !== undefined,
    price: raw.price as string | undefined,
    volume: raw.volume as string | undefined,
    state: raw.state as string | undefined,
    states: raw.states as string | undefined,
    orderId: raw["order-id"] as string | undefined,
    orderIds: raw["order-ids"] as string | undefined,
    clientOrderIds: raw["client-order-ids"] as string | undefined,
    orderBy: raw["order-by"] as string | undefined,
    cursor: raw.cursor as string | undefined,
    daysAgo: raw["days-ago"] as string | undefined,
    convertingPriceUnit: raw["converting-price-unit"] as string | undefined,
    page: raw.page as string | undefined,
    limit: raw.limit as string | undefined,
    tool: raw.tool as string | undefined,
    since: raw.since as string | undefined,
    level: raw.level as string | undefined,
    currency: raw.currency as string | undefined,
    netType: raw["net-type"] as string | undefined,
    address: raw.address as string | undefined,
    secondaryAddress: raw["secondary-address"] as string | undefined,
    exchangeName: raw["exchange-name"] as string | undefined,
    receiverType: raw["receiver-type"] as string | undefined,
    receiverKoName: raw["receiver-ko-name"] as string | undefined,
    receiverEnName: raw["receiver-en-name"] as string | undefined,
    receiverCorpKoName: raw["receiver-corp-ko-name"] as string | undefined,
    receiverCorpEnName: raw["receiver-corp-en-name"] as string | undefined,
    amount: raw.amount as string | undefined,
    twoFactorType: raw["two-factor-type"] as string | undefined,
    txids: raw.txids as string | undefined,
    txid: raw.txid as string | undefined,
    withdrawalId: raw["withdrawal-id"] as string | undefined,
    withdrawalIds: raw["withdrawal-ids"] as string | undefined,
    depositId: raw["deposit-id"] as string | undefined,
    depositIds: raw["deposit-ids"] as string | undefined,
    duration: raw.duration as string | undefined,
    frequency: raw.frequency as string | undefined,
    algoOrderId: raw["algo-order-id"] as string | undefined,
    nextKey: raw["next-key"] as string | undefined,
    file: raw.file as string | undefined,
  };

  return { values, positionals };
}

// Helper: convert comma-separated string to array
export function toArray(value?: string): string[] | undefined {
  if (!value) return undefined;
  return value.split(",").map((s) => s.trim()).filter(Boolean);
}

// Helper: parse a JSON array-of-strings flag value (txids only). Unlike toArray,
// this does NOT split on commas — txid real-data contains commas and spaces
// (e.g. "EVENT_COUPON:4,649", "2025-07-31 15:12:24.407715"), and per-network
// txid formats are unbounded, so a delimiter cannot safely separate them. We
// align the CLI with the MCP `txids` array input by requiring a JSON array
// string: --txids '["txid1","txid2"]'. There is intentionally no comma fallback
// (ITQA-55503) — a bare comma-separated value is rejected with a friendly hint
// rather than silently mis-split.
export function parseJsonStringArray(
  flag: string,
  value?: string,
): string[] | undefined {
  if (!value) return undefined;
  const hint = `Invalid --${flag}: must be a JSON array of strings, e.g. --${flag} '["txid1","txid2"]'.`;
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    throw new CliUsageError(hint);
  }
  if (!Array.isArray(parsed) || !parsed.every((s) => typeof s === "string")) {
    throw new CliUsageError(hint);
  }
  return parsed.map((s) => s.trim()).filter(Boolean);
}

// Helper: convert string to number or undefined.
// When `flag` is provided, a non-numeric string raises a friendly
// CliUsageError instead of silently returning undefined — otherwise downstream
// validators (parseRangedInt / parseEnumInt / parsePositiveInt) would
// pass-through and the user's typo (e.g. `--unit abc`) would silently fall
// back to a default. Backward-compatible when `flag` is omitted.
export function toNumber(value?: string, flag?: string): number | undefined {
  if (value === undefined || value === null) return undefined;
  const n = Number(value);
  if (Number.isNaN(n)) {
    if (flag !== undefined) {
      throw new CliUsageError(
        `Invalid --${flag}: must be a number. Got '${value}'.`,
      );
    }
    return undefined;
  }
  return n;
}

// Helper: guard against ISO 8601 timezone offsets in candle/trade --to values.
// Bithumb's candle and trade endpoints reject offset-bearing datetimes
// (e.g. "2026-05-29T00:00:00+09:00") with HTTP 400 Invalid parameter.
// LLMs that consume the bithumb-market skill default to attaching offsets,
// so we surface a friendly CliUsageError before the request leaves the CLI.
// Non-offset values (undefined, empty, naive datetime, free-form text) are
// returned unchanged — Bithumb still owns format validation for those.
const TIMEZONE_OFFSET_PATTERN = /(?:Z|[+\-]\d{2}:?\d{2})$/;

export function parseKstDatetime(value: string | undefined): string | undefined {
  if (value === undefined || value === "") return value;
  if (TIMEZONE_OFFSET_PATTERN.test(value)) {
    throw new CliUsageError(
      "Invalid --to: timezone offset is not supported. " +
        "Bithumb API requires KST naive datetime (no offset). " +
        "Use YYYY-MM-DDTHH:MM:SS, e.g. 2026-01-01T00:00:00",
    );
  }
  return value;
}

// Guard for `bithumb market trades --to`. Unlike candles, the trades endpoint
// `/v1/trades/ticks` accepts time-of-day only (HHmmss or HH:mm:ss,
// 00:00:00–23:59:59). Date-bearing values like "2026-05-31T23:00:00" are
// rejected by Bithumb with HTTP 400 — surface a friendly CliUsageError up
// front so users (and LLMs that copy the candles to-format) get an actionable
// hint instead of an opaque API error. The same TIMEZONE_OFFSET_PATTERN guard
// applies — offsets like +09:00 or Z are rejected as well.
export function parseKstTimeOfDay(value: string | undefined): string | undefined {
  if (value === undefined || value === "") return value;
  if (value.includes("T") || value.includes("-")) {
    throw new CliUsageError(
      "Invalid --to: trades expects time-of-day only, not a date. " +
        "Use HHmmss or HH:mm:ss (00:00:00–23:59:59), e.g. 230000 or 23:00:00. " +
        "For past days use --days-ago (1–7).",
    );
  }
  if (TIMEZONE_OFFSET_PATTERN.test(value)) {
    throw new CliUsageError(
      "Invalid --to: timezone offset is not supported. " +
        "Use HHmmss or HH:mm:ss (KST, no offset), e.g. 230000 or 23:00:00.",
    );
  }
  return value;
}

// Helper: validate that a numeric option falls within an inclusive [min, max]
// range and is an integer. Bithumb endpoints reject out-of-range values at the
// API layer with opaque errors, so we surface a friendly CliUsageError before
// the request leaves the CLI. Pass-through on undefined so callers can decide
// the default. Used for options like --count where the upstream API enforces
// per-endpoint upper bounds (notices: 20, candles: 200, trades: 500).
export function parseRangedInt(
  flag: string,
  value: number | undefined,
  min: number,
  max: number,
): number | undefined {
  if (value === undefined) return undefined;
  if (!Number.isInteger(value) || value < min || value > max) {
    throw new CliUsageError(
      `Invalid --${flag}: must be between ${min} and ${max}. Got ${value}.`,
    );
  }
  return value;
}

// Helper: validate that a numeric option is an integer >= min. Used for
// options like --page and trade/twap --limit where Bithumb's spec defines a
// lower bound (1) but no upper bound. Same pass-through and error shape as
// parseRangedInt; the error message omits a max so we don't fabricate a
// constraint that the spec doesn't declare.
export function parsePositiveInt(
  flag: string,
  value: number | undefined,
  min = 1,
): number | undefined {
  if (value === undefined) return undefined;
  if (!Number.isInteger(value) || value < min) {
    throw new CliUsageError(
      `Invalid --${flag}: must be an integer >= ${min}. Got ${value}.`,
    );
  }
  return value;
}

// Helper: validate that a numeric option matches one of a discrete allowed
// set. Used for options like candles-minutes --unit where Bithumb only accepts
// specific values (1, 3, 5, 10, 15, 30, 60, 240). Same pass-through and error
// shape as parseRangedInt.
export function parseEnumInt(
  flag: string,
  value: number | undefined,
  allowed: readonly number[],
): number | undefined {
  if (value === undefined) return undefined;
  if (!allowed.includes(value)) {
    throw new CliUsageError(
      `Invalid --${flag}: must be one of ${allowed.join(", ")}. Got ${value}.`,
    );
  }
  return value;
}

// Helper: validate that a string option matches one of a discrete allowed set,
// case-sensitively. Used for deposit/withdraw list --state, where Bithumb
// accepts only specific UPPERCASE values per endpoint and rejects anything else
// (including lowercase) with an opaque `validation_error`. We surface a friendly
// CliUsageError before the request leaves the CLI, naming the flag, the rejected
// value, and the full per-endpoint whitelist. Validation is intentionally
// case-sensitive: the API contract is uppercase, and silently upcasing would
// both hide that contract and be impossible for coin deposit's compound values
// (e.g. DEPOSIT_ACCEPTED). Same pass-through and error shape as parseEnumInt.
export function parseEnumString(
  flag: string,
  value: string | undefined,
  allowed: readonly string[],
): string | undefined {
  if (value === undefined) return undefined;
  if (!allowed.includes(value)) {
    throw new CliUsageError(
      `Invalid --${flag}: must be one of ${allowed.join(", ")}. Got '${value}'.`,
    );
  }
  return value;
}
